// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint128 amount) public {
        vm.assume(actor != address(0));
        uint128 amt = amount % 1 ether;
        vm.assume(amt > 0);

        vm.deal(actor, amt);

        vm.prank(actor);
        c.deposit{value: amt}();

        bool ok1;
        vm.prank(actor);
        try c.withdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        vm.prank(actor);
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!(ok1 == true && ok2 == false));
    }
}
